import 'package:flutter/material.dart'; enum Provenance { manual, synced, estimated } class ProvenanceBadge extends StatelessWidget{final Provenance provenance; const ProvenanceBadge({super.key, required this.provenance}); Color _color()=> provenance==Provenance.manual? Colors.orange : provenance==Provenance.synced? Colors.green : Colors.blueGrey; @override Widget build(BuildContext c)=>Container(padding: const EdgeInsets.symmetric(horizontal:8, vertical:4), decoration: BoxDecoration(color: _color().withOpacity(.15), borderRadius: BorderRadius.circular(8)), child: Text(provenance.name));}
